package elkslop.electron

/**
 * Sixteen hardware pens mapped to eight RGB colours. Palette bits are inverted.
 * The unusual wiring is documented in the Advanced User Guide, section 14.1.
 * Flashing colours and the cursor are generated by the OS, not this hardware.
 */
class UlaPalette internal constructor() {
    private val registers = IntArray(8) { 0xFF }
    private val colours = IntArray(16)

    /** RGB colour number: bit 0 red, bit 1 green, bit 2 blue. */
    fun colour(pen: Int): Int {
        require(pen in 0..15)
        return colours[pen]
    }

    fun rgb(pen: Int): Int {
        val colour = colour(pen)
        return (if (colour and 1 != 0) 0xFF0000 else 0) or
            (if (colour and 2 != 0) 0x00FF00 else 0) or
            (if (colour and 4 != 0) 0x0000FF else 0)
    }

    internal fun write(register: Int, value: Int) {
        registers[register] = value and 0xFF
        val pair = register / 2
        val even = registers[pair * 2] xor 0xFF
        val odd = registers[pair * 2 + 1] xor 0xFF
        val firstPen = PEN_GROUPS[pair]
        for (slot in 0..3) {
            val pen = firstPen + (slot and 1) * 2 + (slot ushr 1) * 8
            val red = (odd ushr slot) and 1
            val green = if (slot < 2) (odd ushr (slot + 4)) and 1 else (even ushr slot) and 1
            val blue = (even ushr (slot + 4)) and 1
            colours[pen] = red or (green shl 1) or (blue shl 2)
        }
    }

    private companion object {
        val PEN_GROUPS = intArrayOf(0, 4, 5, 1)
    }
}
